package com.example.lebiais.sonde

import androidx.compose.foundation.ExperimentalFoundationApi
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.imePadding
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.relocation.BringIntoViewRequester
import androidx.compose.foundation.relocation.bringIntoViewRequester
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.material3.TextField
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.focus.onFocusChanged
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.delay

private class Fiche(val champs: List<String>)

/**
 * Six champs, dont un collé au bas de l'écran. Quand un champ a le focus, une
 * réserve s'ouvre sous le dernier (le clavier d'iOS ne rétrécit pas la page) et
 * le champ actif est ramené à l'écran une fois le clavier monté.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
fun EcranSaisie() {
    val libelles = listOf("Nom", "Boucle (numérique)", "Date", "Poids (décimal)", "Notes", "Dernier champ, collé au bas")
    val claviers = listOf(KeyboardType.Text, KeyboardType.Number, KeyboardType.Text, KeyboardType.Decimal, KeyboardType.Text, KeyboardType.Text)
    val lignes = listOf(1, 1, 1, 1, 4, 1)
    val valeurs = remember { mutableStateListOf("", "", "", "", "", "") }
    val fiches = remember { mutableStateListOf<Fiche>() }
    var focus by remember { mutableStateOf<Int?>(null) }
    val demandeurs = remember { List(6) { BringIntoViewRequester() } }

    // Le clavier met un moment à monter : on attend, puis on ramène le champ.
    LaunchedEffect(focus) {
        val f = focus ?: return@LaunchedEffect
        delay(350)
        demandeurs[f].bringIntoView()
    }

    @Composable
    fun champ(i: Int) {
        TextField(
            value = valeurs[i],
            onValueChange = { valeurs[i] = it },
            label = { Text(libelles[i]) },
            minLines = lignes[i],
            keyboardOptions = KeyboardOptions(keyboardType = claviers[i]),
            modifier = Modifier.fillMaxWidth().padding(vertical = 6.dp)
                .bringIntoViewRequester(demandeurs[i])
                .onFocusChanged { e -> if (e.isFocused) focus = i else if (focus == i) focus = null },
        )
    }

    Column(Modifier.fillMaxSize().imePadding().verticalScroll(rememberScrollState()).padding(16.dp)) {
        Text("Essayez : accents (é, è, ç, œ), majuscule automatique, correction automatique, copier-coller, dictée.")
        for (i in 0..4) champ(i)
        Button(
            onClick = {
                fiches.add(Fiche(valeurs.toList()))
                for (i in valeurs.indices) valeurs[i] = ""
            },
            modifier = Modifier.padding(vertical = 8.dp),
        ) { Text("Enregistrer") }
        Text("${fiches.size} fiche(s) en mémoire")
        Spacer(Modifier.height(280.dp))
        champ(5)
        // Réserve sous le dernier champ, le temps que le clavier occupe le bas.
        Spacer(Modifier.height(if (focus != null) 360.dp else 24.dp))
    }
}
