/** Un écran du menu : son titre, la phrase qui dit quoi essayer, son contenu. */
class Ecran(val titre: String, val consigne: String, val contenu: @Composable () -> Unit)

/**
 * Les écrans du menu, dans l'ordre. UNE LIGNE PAR ÉCRAN, virgule finale : les
 * tâches 3 à 6 ajoutent la leur à l'endroit de leur commentaire, sans se
 * marcher dessus. Exemple : `Ecran("Stockage", "Écrire, relire.") { EcranStockage() },`
 */
private fun ecransDeLaSonde(): List<Ecran> = listOf(
    // Stockage (tâche 3)
    Ecran("Stockage", "Écrivez 50 Mo, relisez-les, puis demandez le stockage persistant. À refaire 8 jours plus tard, sans réécrire.") { EcranStockage() },
    Ecran("Saisie", "Saisir accents, majuscules, dictée, copier-coller ; le dernier champ doit rester au-dessus du clavier.") { EcranSaisie() },
    Ecran("Liste", "Faire défiler vite la liste des 300 bêtes et lire les images par seconde.") { EcranListe() },
    Ecran("Carte", "Glisser, pincer ou molette ; changer de fond ; lire les images par seconde et les tuiles refusées.") { EcranCarte() },
    Ecran("Photos", "Prendre ou choisir des photos : elles restent toutes en mémoire, regarder le total.") { EcranPhotos() },
    Ecran("Infos", "Lire la version, le build, les marges sûres et le temps d'ouverture ; relancer pour comparer.") { EcranInfos() },
)

private val PAPIER = Color(0xFFFFFBF2)
private val ENCRE = Color(0xFF1F1B16)

/** Les marges sûres courantes (encoche, barre d'accueil), relues à chaque rotation ou redimensionnement. */
internal val LocalMarges = compositionLocalOf { MargesSures(0.0, 0.0, 0.0, 0.0) }

/**
 * Lit les marges sûres, et les relit quand la taille de la fenêtre change (rotation,
 * redimensionnement : le canevas suit `resize`). `env()` se met à jour un instant après : deuxième lecture différée.
 */
@Composable
private fun margesSuresCourantes(): MargesSures {
    val taille = LocalWindowInfo.current.containerSize
    var marges by remember { mutableStateOf(Navigateur.margesSures()) }
    LaunchedEffect(taille) {
        marges = Navigateur.margesSures()
        delay(300)
        marges = Navigateur.margesSures()
    }
    return marges
}

/** La racine de l'interface. */
@Composable
fun Sonde() {
    val police = policeSonde()
    // Le temps d'ouverture se lit à la première image dessinée.
    LaunchedEffect(Unit) {
        withFrameNanos { }
        Ouverture.noter()
    }
    MaterialTheme(typography = typographieSonde(police)) {
        val marges = margesSuresCourantes()
        val ecrans = remember { ecransDeLaSonde() }
        var courant by remember { mutableStateOf<Ecran?>(null) }
        CompositionLocalProvider(LocalMarges provides marges) {
            Column(Modifier.fillMaxSize().background(PAPIER)) {
                Bandeau(marges)
                // Gauche, droite et bas : le contenu reste hors de l'encoche (paysage) et de la barre d'accueil.
                Column(
                    Modifier.fillMaxSize().padding(start = marges.gauche.dp, end = marges.droite.dp, bottom = marges.bas.dp),
                ) {
                    val ecran = courant
                    if (ecran == null) {
                        Menu(ecrans) { courant = it }
                    } else {
                        Text(
                            "‹ Menu",
                            color = ENCRE,
                            fontSize = 16.sp,
                            modifier = Modifier.clickable { courant = null }.padding(16.dp),
                        )
                        Text(ecran.consigne, color = ENCRE, fontSize = 14.sp, modifier = Modifier.padding(horizontal = 16.dp))
                        ecran.contenu()
                    }
                }
            }
        }
    }
}

/** La version chargée et le build, en permanence en haut de chaque écran. */
@Composable
private fun Bandeau(marges: MargesSures) {
    Row(
        Modifier.fillMaxWidth().background(ENCRE)
            .padding(top = marges.haut.dp, start = (16 + marges.gauche).dp, end = (16 + marges.droite).dp),
        horizontalArrangement = Arrangement.SpaceBetween,
    ) {
        Text(
            "Le Biais — sonde · ${Navigateur.version} · build ${Navigateur.build()}",
            color = PAPIER,
            fontSize = 13.sp,
            modifier = Modifier.padding(vertical = 10.dp),
        )
    }
}

@Composable
private fun Menu(ecrans: List<Ecran>, ouvrir: (Ecran) -> Unit) {
    Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)) {
        if (ecrans.isEmpty()) {
            Text("Aucun écran pour l'instant.", color = ENCRE)
        }
        for (e in ecrans) {
            Text(
                e.titre,
                color = ENCRE,
                fontSize = 20.sp,
                modifier = Modifier.fillMaxWidth().clickable { ouvrir(e) }.padding(vertical = 14.dp),
            )
        }
    }
}
