package com.example.lebiais.sonde

import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.withContext
import kotlin.coroutines.cancellation.CancellationException
import kotlin.time.TimeSource

sealed interface Resultat {
    data class Reussi(val octets: Long, val ms: Double) : Resultat
    data class Echec(val message: String) : Resultat
}

/** Écrit un morceau ; lève en cas d'échec (dont `QuotaExceededError`). */
fun interface Ecrivain {
    suspend fun ecrire(nom: String, rang: Int, morceau: ByteArray)

    /**
     * Appelé une fois, quand l'écriture est finie : [reussi] vrai après le dernier
     * morceau (on ferme et valide le fichier), faux si un morceau a échoué ou
     * si l'on abandonne (on jette ce qui est écrit). Par défaut, rien à fermer.
     */
    suspend fun terminer(nom: String, reussi: Boolean) {}
}

const val NOM_FICHIER = "essai50.bin"
const val TAILLE_MORCEAU = 1_048_576
const val MORCEAUX_A_ECRIRE = 50

/** Écrit les morceaux dans l'ordre ; rattrape l'échec et chronomètre. */
suspend fun ecrireAvec(ecrivain: Ecrivain, vararg morceaux: ByteArray): Resultat =
    ecrireAvec(ecrivain, morceaux.size) { morceaux[it] }

/** Comme ci-dessus, mais produit chaque morceau à son tour : 50 Mo ne tiennent pas tous en mémoire d'un coup. */
suspend fun ecrireAvec(ecrivain: Ecrivain, nombre: Int, morceau: (Int) -> ByteArray): Resultat {
    val depart = TimeSource.Monotonic.markNow()
    var total = 0L
    return try {
        for (rang in 0 until nombre) {
            val m = morceau(rang)
            ecrivain.ecrire(NOM_FICHIER, rang, m)
            total += m.size
        }
        ecrivain.terminer(NOM_FICHIER, true)
        Resultat.Reussi(total, depart.elapsedNow().inWholeMicroseconds / 1000.0)
    } catch (e: CancellationException) {
        abandonner(ecrivain)
        throw e
    } catch (e: Throwable) {
        abandonner(ecrivain)
        Resultat.Echec(e.message ?: e.toString())
    }
}

/** Jette l'écriture en cours, même si la coroutine est annulée ; une erreur ici ne cache pas la première. */
private suspend fun abandonner(ecrivain: Ecrivain) {
    withContext(NonCancellable) {
        try { ecrivain.terminer(NOM_FICHIER, false) } catch (_: Throwable) { }
    }
}

/** Relit le fichier morceau par morceau, dans l'ordre. [lireMorceau] rend la réponse brute de sonde.js (voir [contenuDe]) ; contenu vide à la fin. */
suspend fun lireParMorceaux(
    nom: String,
    parMorceau: (ByteArray) -> Unit,
    lireMorceau: suspend (String, Int) -> String,
): Resultat {
    val depart = TimeSource.Monotonic.markNow()
    var total = 0L
    return try {
        var rang = 0
        while (true) {
            val texte = contenuDe(lireMorceau(nom, rang))
            if (texte.isEmpty()) break
            val octets = texteEnOctets(texte)
            parMorceau(octets)
            total += octets.size
            rang++
        }
        Resultat.Reussi(total, depart.elapsedNow().inWholeMicroseconds / 1000.0)
    } catch (e: CancellationException) {
        throw e
    } catch (e: Throwable) {
        Resultat.Echec(e.message ?: e.toString())
    }
}

/** Un octet par caractère (0..255) : le plus rapide à passer entre Kotlin et JavaScript, sur les deux cibles. */
fun octetsEnTexte(octets: ByteArray): String =
    CharArray(octets.size) { (octets[it].toInt() and 0xFF).toChar() }.concatToString()

fun texteEnOctets(texte: String): ByteArray = ByteArray(texte.length) { texte[it].code.toByte() }

/**
 * Le canal d'erreur est séparé du contenu : chaque réponse de sonde.js
 * (écriture, lecture) commence par un caractère d'état, `O` (réussi, le
 * contenu suit) ou `E` (échec, le message suit). Le contenu, lui, est libre :
 * il peut commencer par n'importe quel octet, dont 0.
 */
const val ETAT_REUSSI = 'O'
const val ETAT_ECHEC = 'E'

fun reponseDeContenu(contenu: String): String = ETAT_REUSSI + contenu

fun reponseDErreur(message: String): String = ETAT_ECHEC + message

/** Le contenu d'une réponse de sonde.js ; lève `Exception(message)` si elle est un échec. */
fun contenuDe(reponse: String): String = when {
    reponse.startsWith(ETAT_REUSSI) -> reponse.substring(1)
    reponse.startsWith(ETAT_ECHEC) -> throw Exception(reponse.substring(1))
    else -> throw Exception("réponse inattendue du navigateur")
}
