/** Une photo gardée en mémoire : son image décodée, ou rien si Skia ne l'a pas lue. */
private class PhotoGardee(val image: ImageBitmap?, val typeMime: String, val octets: Int) {
    /** Ce que pèse l'image décodée en mémoire (0 si elle n'est pas lue). */
    val octetsDecodes: Long = image?.let { octetsDecodes(it.width, it.height) } ?: 0L
}

/**
 * La mémoire d'une image décodée : 4 octets (RGBA) par pixel. C'est elle, pas le
 * fichier JPEG compressé, qui décide si l'appareil tient quand on garde des dizaines de photos.
 */
internal fun octetsDecodes(largeur: Int, hauteur: Int): Long = largeur.toLong() * hauteur * 4

@Composable
fun EcranPhotos() {
    val photos = remember { mutableStateListOf<PhotoGardee>() }
    val scope = rememberCoroutineScope()
    val compresses = photos.sumOf { it.octets.toLong() }
    val decodes = photos.sumOf { it.octetsDecodes }

    Column(Modifier.fillMaxSize().padding(16.dp)) {
        // UNDISPATCHED : la coroutine démarre tout de suite, dans le clic, et ouvre le sélecteur
        // avant sa première suspension. Une coroutine lancée « plus tard » perdrait le geste de l'utilisateur (iOS).
        fun ajouter(capture: Boolean) = scope.launch(start = CoroutineStart.UNDISPATCHED) {
            val choisie = Navigateur.choisirPhoto(capture) ?: return@launch
            photos.add(PhotoGardee(Navigateur.decoderImage(choisie.octets), choisie.typeMime, choisie.octets.size))
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(onClick = { ajouter(true) }) { Text("Prendre une photo") }
            Button(onClick = { ajouter(false) }) { Text("Choisir une photo") }
        }
        Text(
            "${photos.size} photos · ${mo(compresses)} Mo compressés · ≈ ${mo(decodes)} Mo décodés en mémoire",
            fontSize = 14.sp,
            color = Color(0xFF1F1B16),
            modifier = Modifier.padding(vertical = 8.dp),
        )
        LazyVerticalGrid(GridCells.Adaptive(120.dp), Modifier.fillMaxSize()) {
            items(photos) { p ->
                Box(
                    Modifier.padding(2.dp).fillMaxWidth().aspectRatio(1f).background(Color(0xFFE8E0D0)),
                    contentAlignment = Alignment.Center,
                ) {
                    if (p.image != null) {
                        Image(p.image, null, Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
                    } else {
                        Text("format non lu : ${p.typeMime.ifEmpty { "type inconnu" }}", fontSize = 12.sp, color = Color(0xFFB3261E), modifier = Modifier.padding(6.dp))
                    }
                }
            }
        }
    }
}
