package com.example.lebiais.sonde

/** Une bête de pacotille pour l'essai de la liste. */
data class BeteFictive(val boucle: String, val nom: String, val note: String)

private val PRENOMS = listOf(
    "Éloïse", "Hélène", "Zoé", "Noémie", "Gaëlle", "Chloé", "Océane", "Joséphine", "Françoise", "Mélusine",
    "Cérès", "Étoile", "Brunette", "Gazelle", "Colombe", "Pâquerette", "Hortense", "Ophélie", "Séverine", "Léa",
    "Thérèse", "Amélie", "Irène", "Clémence", "Rosalie", "Berthe", "Mirabelle", "Fanchon", "Ysée", "Lucie",
)

private val NOTES = listOf(
    "Agnelage facile, deux agneaux vigoureux.",
    "Boite légèrement de l'arrière gauche depuis la dernière rotation.",
    "À surveiller : mamelle dure, parage des onglons à refaire.",
    "Très docile, suit le troupeau sans les chiens.",
    "Vermifugée à la montée en estive, prochaine dose à l'automne.",
    "Née à la bergerie de l'Écot ; mère : brebis à la tache noire.",
    "Œil gauche larmoyant, contrôlé à la visite du vétérinaire.",
)

/** [nombre] bêtes aux boucles toutes différentes (`FR 0 04 123 0001`, …), noms accentués, notes de deux à trois lignes. */
fun troupeauFictif(nombre: Int): List<BeteFictive> = List(nombre) { i ->
    val boucle = "FR 0 04 ${(123 + i / 100).toString().padStart(3, '0')} ${(i % 100 + 1).toString().padStart(4, '0')}"
    val nom = PRENOMS[i % PRENOMS.size] + if (i >= PRENOMS.size) " ${i / PRENOMS.size + 1}" else ""
    val lignes = 2 + i % 2
    val note = List(lignes) { k -> NOTES[(i * 3 + k * 2) % NOTES.size] }.joinToString("\n")
    BeteFictive(boucle, nom, note)
}
